const { MongoClient } = require("mongodb");

async function main() {
  const client = new MongoClient(
    "mongodb://app_user:devsecret@127.0.0.1:27017/?authSource=inventory",
    { maxPoolSize: 20, serverSelectionTimeoutMS: 5000 }
  );

  await client.connect();
  const db = client.db("inventory");
  const reply = await db.command({ ping: 1 });
  console.log(reply.ok === 1 ? "connected" : "no reply");

  await client.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

// Which node answered and which user is authenticated?
db.hello()
db.runCommand({ connectionStatus: 1 })

// List databases with their on-disk size
show dbs

// Select a database; it exists only after the first write
use inventory
db.getName()

// Counters for the current database: collections, objects, indexes, storage
db.stats()
db.stats(1024 * 1024)  // sizes in MiB

// Delete the selected database and every collection inside it
db.dropDatabase()

// A JSON schema rejects documents that miss required fields
db.createCollection("orders", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["customerId", "total", "status"],
      properties: {
        customerId: { bsonType: "objectId" },
        total: { bsonType: "decimal" },
        status: { enum: ["pending", "paid", "shipped"] },
      },
    },
  },
  validationLevel: "strict",
  validationAction: "error",
})

show collections

// Capped collection: fixed byte budget, oldest documents fall off
db.createCollection("events", { capped: true, size: 1048576, max: 5000 })

// Time series collection for timestamped measurements
db.createCollection("readings", {
  timeseries: { timeField: "at", metaField: "sensor", granularity: "minutes" },
  expireAfterSeconds: 86400,
})

// Rename inside the same database, then remove it
db.orders.renameCollection("orders_2025")
db.orders_2025.drop()

// Read back options and validation rules
db.getCollectionInfos({ name: "orders" })

// Read nested values with dot paths
const product = db.products.findOne({ sku: "KB-87" })
product.dimensions.width
product.tags[0]
Object.keys(product)

// BSON types survive the round trip
product.price instanceof Decimal128  // true
product.createdAt instanceof Date    // true

// insertOne returns the generated _id when the document omits it
db.orders.insertOne({
  customerId: ObjectId("665f1c2ab7e4a91d3c8f0a12"),
  total: NumberDecimal("249.50"),
  status: "pending",
  items: [{ sku: "KB-87", qty: 1 }, { sku: "MS-12", qty: 2 }],
  createdAt: new Date(),
})

// ordered: false keeps going after a duplicate key error
const result = db.orders.insertMany(
  [
    { customerId: ObjectId("665f1c2ab7e4a91d3c8f0a13"), total: NumberDecimal("59.90"), status: "paid" },
    { customerId: ObjectId("665f1c2ab7e4a91d3c8f0a14"), total: NumberDecimal("18.00"), status: "pending" },
  ],
  { ordered: false }
)

result.insertedCount

// Mix inserts, updates and deletes in one ordered batch
db.products.bulkWrite([
  { insertOne: { document: { sku: "HD-45", name: "Headset", price: NumberDecimal("89.00") } } },
  { updateOne: { filter: { sku: "KB-87" }, update: { $set: { inStock: false } } } },
  { deleteOne: { filter: { sku: "MS-12" } } },
])

// All documents, then one document by primary key
db.orders.find().pretty()
db.orders.findOne({ _id: ObjectId("665f1c2ab7e4a91d3c8f0a12") })

// Projection: include two fields and hide _id
db.orders.find(
  { status: "paid" },
  { total: 1, status: 1, _id: 0 }
)

// The server applies sort, skip and limit; the shell fetches lazily
db.orders
  .find({ status: "pending" })
  .sort({ createdAt: -1 })
  .skip(20)
  .limit(10)

// Count and iterate without materializing the whole result set
db.orders.countDocuments({ status: "pending" })
for (const order of db.orders.find({ status: "pending" })) {
  print(order._id, order.total)
}

// Regular expression, logical composition and ordering
db.customers.find({ email: { $regex: "@example[.]com$", $options: "i" } })
db.orders.find({
  $or: [{ status: "paid" }, { total: { $gt: NumberDecimal("500.00") } }],
})
db.orders.find({
  $and: [{ status: "paid" }, { createdAt: { $gte: new Date("2026-01-01") } }],
}).sort({ total: -1, createdAt: 1 })

// Field operators touch only the named paths
db.orders.updateOne(
  { _id: ObjectId("665f1c2ab7e4a91d3c8f0a12") },
  {
    $set: { status: "paid", paidAt: new Date() },
    $inc: { "totals.tax": NumberDecimal("12.45") },
  }
)

// Update every match and report how many documents changed
const changed = db.orders.updateMany(
  { status: "pending" },
  { $set: { reviewed: false } }
)
changed.modifiedCount

// Upsert inserts a new document when the filter matches nothing
db.settings.updateOne(
  { key: "theme" },
  { $set: { value: "dark", updatedAt: new Date() } },
  { upsert: true }
)

// Array operators: append, avoid duplicates and remove matches
db.orders.updateOne(
  { _id: ObjectId("665f1c2ab7e4a91d3c8f0a12") },
  {
    $push: { events: { at: new Date(), type: "paid" } },
    $addToSet: { tags: "priority" },
    $pull: { items: { sku: "MS-12" } },
  }
)

// Return the document after the change
db.orders.findOneAndUpdate(
  { _id: ObjectId("665f1c2ab7e4a91d3c8f0a12") },
  { $set: { status: "shipped" } },
  { returnDocument: "after" }
)

// One match, then every match, then the affected count
db.orders.deleteOne({ _id: ObjectId("665f1c2ab7e4a91d3c8f0a12") })
const { deletedCount } = db.orders.deleteMany({
  status: "cancelled",
  createdAt: { $lt: new Date("2025-01-01") },
})
deletedCount

// Remove and return the oldest queued job in one round trip
db.jobs.findOneAndDelete(
  { status: "queued" },
  { sort: { createdAt: 1 } }
)

// TTL index: the server removes documents after expiresAt passes
db.sessions.createIndex({ expiresAt: 1 }, { expireAfterSeconds: 0 })

// Partial index: only documents matching the filter are indexed
db.orders.createIndex(
  { total: -1 },
  { partialFilterExpression: { status: "paid" } }
)

// Text index, then a full-text search
db.products.createIndex({ name: "text", description: "text" })
db.products.find({ $text: { $search: "wireless keyboard" } })

// Inspect the winning plan and the index list
db.orders.find({ status: "paid" }).explain("executionStats")
db.orders.getIndexes()

// Drop by generated name
db.orders.dropIndex("status_1")

// Flatten line items and enrich each one with its product
db.orders.aggregate([
  { $match: { status: "paid" } },
  { $unwind: "$items" },
  {
    $lookup: {
      from: "products",
      localField: "items.sku",
      foreignField: "sku",
      as: "product",
    },
  },
  { $unwind: "$product" },
  { $project: { _id: 0, sku: "$items.sku", name: "$product.name", qty: "$items.qty" } },
])

// Two reports over the same input in a single pass
db.orders.aggregate([
  { $match: { createdAt: { $gte: ISODate("2026-01-01T00:00:00Z") } } },
  {
    $facet: {
      byStatus: [{ $group: { _id: "$status", count: { $sum: 1 } } }],
      monthly: [
        {
          $group: {
            _id: { $dateToString: { format: "%Y-%m", date: "$createdAt" } },
            revenue: { $sum: "$total" },
          },
        },
        { $sort: { _id: 1 } },
      ],
    },
  },
])

const { MongoClient } = require("mongodb");

async function transfer(client, fromId, toId, amountCents) {
  const session = client.startSession();
  try {
    // withTransaction retries transient errors and aborts on a throw
    await session.withTransaction(async () => {
      const accounts = client.db("bank").collection("accounts");

      const debit = await accounts.updateOne(
        { _id: fromId, balanceCents: { $gte: amountCents } },
        { $inc: { balanceCents: -amountCents } },
        { session }
      );
      if (debit.matchedCount !== 1) throw new Error("insufficient funds");

      await accounts.updateOne(
        { _id: toId },
        { $inc: { balanceCents: amountCents } },
        { session }
      );
    });
  } finally {
    await session.endSession();
  }
}

// mongosh: requires a replica set or a sharded cluster
const session = db.getMongo().startSession()
session.startTransaction()

try {
  const accounts = session.getDatabase("bank").accounts
  accounts.updateOne({ _id: "ana" }, { $inc: { balanceCents: -5000 } })
  accounts.updateOne({ _id: "bruno" }, { $inc: { balanceCents: 5000 } })
  session.commitTransaction()
} catch (error) {
  session.abortTransaction()
  throw error
} finally {
  session.endSession()
}
